/*
 * A095119  Numbers k such that s(k) >= sigma(k), where s(k) = A095118(k) is
 *          the sum of the squares of the divisors of k which are <= sqrt(k)
 *          and sigma(k) = A000203(k) is the sum of the divisors of k.
 * https://oeis.org/A095119
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the n‑th integer k such that the sum of the squares of
 *            the divisors of k that are ≤ √k is ≥ σ(k), where σ(k) is the sum
 *            of all divisors of k. The sequence is generated by brute‑force
 *            testing of successive integers and remembering the ones that
 *            satisfy the inequality
 * Range:     u8 n <= 1, u16 n <= 224, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   grow_seq, sigma_of
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

#include "../utils/sigma_of.h"      /* seq_t sigma_of(idx_t n);          */
#include "../utils/grow_seq.h"      /* void grow_seq(seq_t **,size_t*,size_t); */

/* Integer square root for 64‑bit unsigned integers, no floating point. */
static inline idx_t isqrt_u64(idx_t n) {
    idx_t low = 0, high = n;
    while (low <= high) {
        idx_t mid = low + ((high - low) >> 1);
        if (mid == 0 || mid <= n / mid)  /* mid*mid ≤ n without overflow */
            low = mid + 1;
        else
            high = mid - 1;
    }
    return high;
}

/* ------------------------------------------------------------ */
/*  Sequence cache                                          */
/* ------------------------------------------------------------ */
static seq_t *terms = NULL;      /* array of k that satisfy the property      */
static size_t terms_len = 0;     /* number of stored terms                    */
static size_t terms_cap = 0;     /* allocated capacity                        */
static idx_t last_checked = 0;   /* last integer k that has been tested       */

/* Add a new term to the cache. */
static void add_term(idx_t k) {
    grow_seq(&terms, &terms_cap, terms_len + 1);
    terms[terms_len++] = (seq_t)k;
}

/* Compute s(k): sum of d², for all divisors d of k with d ≤ √k. */
static seq_t s_of(idx_t k) {
    seq_t sum = 0;
    idx_t limit = isqrt_u64(k);
    for (idx_t d = 1; d <= limit; ++d) {
        if (k % d == 0) {
            seq_t d_sq = (seq_t)d * (seq_t)d;
            sum += d_sq;
        }
    }
    return sum;
}

/* ------------------------------------------------------------ */
/*  Public interface                                         */
/* ------------------------------------------------------------ */
seq_t a(idx_t n) {
    if (n == 0)      /* undefined for n=0, but guard anyway */
        return (seq_t)0;

    /* Produce terms until we have at least n of them. */
    while (terms_len < n) {
        ++last_checked;
        seq_t sum_s = s_of(last_checked);
        seq_t sigma = sigma_of(last_checked);
        if (sum_s >= sigma)
            add_term(last_checked);
    }
    return terms[n - 1];
}
